local guards_called = false
function event_combat(e)
  if not e.joined or guards_called then return end
  guards_called = true
  local guard1 = eq.spawn2(116552, 0, 0, e.self:GetX() + 15, e.self:GetY() + 5, e.self:GetZ(), e.self:GetHeading())
  guard1:Signal(7)
  local guard2 = eq.spawn2(116552, 0, 0, e.self:GetX() + -15, e.self:GetY() + 5, e.self:GetZ(), e.self:GetHeading())
  guard2:Signal(7)
  local guard3 = eq.spawn2(116552, 0, 0, e.self:GetX() + 0, e.self:GetY() + -15, e.self:GetZ(), e.self:GetHeading())
  guard3:Signal(7)
  eq.set_timer("reset", 7200000)
end
function event_timer(e)
  if e.timer == "reset" then guards_called = false; eq.stop_timer("reset") end
end
function event_death_complete(e) eq.stop_timer("reset") end
